// Record - immutable by default
public record Person(string FirstName, string LastName);

// Usage
var person = new Person("Alice", "Johnson");
Console.WriteLine(person); // Person { FirstName = Alice, LastName = Johnson }

// Records have value-based equality
var person2 = new Person("Alice", "Johnson");
Console.WriteLine(person == person2); // True

// With mutable properties
public record MutablePerson(string FirstName)
{
    public string LastName { get; set; }
}

// Type patterns
object obj = "hello";
switch (obj)
{
    case string s:
        Console.WriteLine($"String: {s}");
        break;
    case int i:
        Console.WriteLine($"Integer: {i}");
        break;
    case null:
        Console.WriteLine("Null");
        break;
    default:
        Console.WriteLine("Unknown");
        break;
}

// Relational patterns
string Grade(int score) => score switch
{
    >= 90 => "A",
    >= 80 => "B",
    >= 70 => "C",
    >= 60 => "D",
    _ => "F"
};
